#!/bin/zsh
# netdoctor.zsh - test the network bottom-up, stop at the first broken layer, suggest a fix
# Usage: netdoctor.zsh [-d domain] [-u url] [-h]
setopt PIPE_FAIL NO_UNSET
zmodload zsh/datetime

domain=example.com url=https://example.com
fails=0 warns=0
iface= myip= gw=
typeset -a fixes
prog=${0:t}

usage() { print -u2 "usage: $prog [-d domain] [-u url]"; exit ${1:-2} }

while getopts ":d:u:h" opt; do
  case $opt in
    d) domain=$OPTARG ;;
    u) url=$OPTARG ;;
    h) usage 0 ;;
    *) usage ;;
  esac
done
shift $(( OPTIND - 1 ))

if [[ -t 1 ]]; then
  c_ok=$'\e[32m' c_warn=$'\e[33m' c_bad=$'\e[31m' c_off=$'\e[0m'
else
  c_ok= c_warn= c_bad= c_off=
fi

ok()   { printf '%s[ OK ]%s %-20s %s\n' "$c_ok" "$c_off" "$1" "$2" }
warn() { printf '%s[WARN]%s %-20s %s\n' "$c_warn" "$c_off" "$1" "$2"; (( ++warns )); [[ -n ${3:-} ]] && fixes+=("$3"); return 0 }
bad()  { printf '%s[FAIL]%s %-20s %s\n' "$c_bad" "$c_off" "$1" "$2"; (( ++fails )); [[ -n ${3:-} ]] && fixes+=("$3"); return 0 }

