def phases(line):
    name, conn, app, start, total = (float(x) for x in line.split())
    if app == 0:
        app = conn
    return {
        "dns": round(name * 1000),
        "tcp": round((conn - name) * 1000),
        "tls": round((app - conn) * 1000),
        "wait": round((start - app) * 1000),
        "download": round((total - start) * 1000),
    }
